    if (!farmer?.phone) return
    const farmerWithPhone = farmer as Farmer & { phone: string }
    requireAuth(() => doAddToCart(item, farmerWithPhone))
  }

  const doAddToCart = (item: ProduceItem, farmer: Farmer & { phone: string }) => {
