                      cart[item.id] ? 'bg-green-600 text-white' : 'bg-green-50 text-green-700'
                    }`}
                  >
                    {adding[item.id] ? (
                      <span className="text-xs leading-none">…</span>
                    ) : cart[item.id] ? (
                      <span className="text-sm leading-none">✓</span>
